.__UIV_SCOPE__ .loader {
  -webkit-perspective: 700px;
  perspective: 700px;
  background: red;
  padding: 10px 20px;
}

.__UIV_SCOPE__ .loader>span {
  font-size: 60px;
  font-family: "franklin gothic medium",sans-serif;
  display: inline-block;
  animation: flip 2.6s infinite linear;
  transform-origin: 0 70%;
  transform-style: preserve-3d;
  -webkit-transform-style: preserve-3d;
}

@keyframes flip {
  35% {
    transform: rotatex(360deg);
  }

  100% {
    transform: rotatex(360deg);
  }
}

.__UIV_SCOPE__ .loader>span:nth-child(even) {
  color: white;
}

.__UIV_SCOPE__ .loader>span:nth-child(2) {
  animation-delay: 0.3s;
}

.__UIV_SCOPE__ .loader>span:nth-child(3) {
  animation-delay: 0.6s;
}

.__UIV_SCOPE__ .loader>span:nth-child(4) {
  animation-delay: 0.9s;
}

.__UIV_SCOPE__ .loader>span:nth-child(5) {
  animation-delay: 1.2s;
}

.__UIV_SCOPE__ .loader>span:nth-child(6) {
  animation-delay: 1.5s
}

.__UIV_SCOPE__ .loader>span:nth-child(7) {
  animation-delay: 1.8s
}
